fn gcd_calc(m: u32, n: u32) -> u32 {
    // Inputs are assumed strictly positive as per the problem statement.
    debug_assert!(m > 0 && n > 0);

    // Use the iterative Euclidean algorithm.
    // Invariants:
    // - a > 0, b > 0
    // - gcd(a, b) == gcd(m, n)
    // Termination measure:
    // - b strictly decreases each step (since b := a % b, and 0 <= a % b < b).
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }

    // a is the gcd. It is positive because m,n > 0 and gcd(m,n) >= 1.
    a
}